code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    # The most frequent value is the background; the distinct sparse mark is connected.
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    for i, (r1, c1) in enumerate(marks):
        for r2, c2 in marks[i + 1:]:
            if r1 == r2:
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if out[r1][c] == bg:
                        out[r1][c] = 3
            elif c1 == c2:
                for r in range(min(r1, r2) + 1, max(r1, r2)):
                    if out[r][c1] == bg:
                        out[r][c1] = 3
    return out
'''
